#!/usr/bin/env python3
"""Replace generic interpretation with numerical findings from the finalized analyzer output."""
import datetime,json,pathlib,statistics,sys
R=pathlib.Path(sys.argv[1]).resolve();S=json.loads((R/'summary.json').read_text());B={x['scenario_id']:x for x in S['scenarios']};GIB=1<<30
rows=[json.loads(x) for x in (R/'results.jsonl').read_text().splitlines()]
def rate(id,unit='GB/s'):
 x=B.get(id)
 if not x:return 'UNAVAILABLE ('+id+')'
 s=x['rates'];v=s['median']/1e12 if unit=='TFLOP/s' else s['median']
 return f"{v:.3f} {unit} (CV {s['cv_percent']:.3f}%, {s['n']} repetitions)"
def latent(id,q='latency_p50_ms'):
 x=B.get(id);v=[y[q] for y in x['latency_per_repeat'] if y.get(q) is not None] if x else []
 return f'{statistics.median(v)*1000:.2f} us' if v else 'UNAVAILABLE'
def fio_tail(id):
 x=B.get(id);v=[z.get('fio_latency',{}).get('percentile',{}).get('99.000000') for z in x['latency_per_repeat']] if x else []
 v=[q for q in v if q is not None]
 return f'{statistics.median(v)/1e6:.3f} ms' if v else 'UNAVAILABLE'
def ratio(a,b):
 return B[b]['rates']['median']/B[a]['rates']['median'] if a in B and b in B else None
def change(a,b):
 v=ratio(a,b);return f'{100*(v-1):+.2f}%' if v is not None else 'UNAVAILABLE'
L=['## Direct numerical answers','','1. **Workload-dependent bottlenecks.** GPU0 warm pinned expert-sized (3 MiB) H2D is '+rate('gpu0-h2d-pinned-3145728')+' and D2H is '+rate('gpu0-d2h-pinned-3145728')+'. GPU0 mapped coalesced and scattered reads are '+rate('gpu0-mapped-coalesced')+' and '+rate('gpu0-mapped-scatter')+'. The scattered kernel is transaction-efficiency-sensitive; this is not a measurement of Strata’s expert kernel. CPU 16-thread read/copy/triad useful payload is '+rate('ram-read-t16')+' / '+rate('ram-copy-t16')+' / '+rate('ram-triad-t16')+'; triad estimates three read/write legs per payload byte. GPU0 FP32 large SGEMM is '+rate('gpu0-gemm-large','TFLOP/s')+' and local-copy payload is '+rate('gpu0-local-copy')+'. SGEMM is a compute surrogate and local copy estimates two device-memory legs. No SM occupancy or physical DRAM channel attribution was measured.','','2. **Supported background budgets.** The table below gives only actually tested points for which every paired repetition meets the indicated useful-work-loss limit and baseline/loaded repetition CV are each <=5%. Unstable baselines remain in the full results but do not support a transfer budget. It does not select a universal budget by taking the largest rate across different workloads. Negative losses are retained and repeated latency samples are correlated.','']
E=json.loads((R/'scheduler-envelope.json').read_text());L+=['| Worst-observed loss ceiling | Workload/transfer pairs satisfying it | Achieved rate GiB/s |','|---|---|---|']
for threshold,value in E['thresholds'].items():
 cases=value['supported_cases']
 L.append('| '+f'{100*float(threshold):g}%'+' | '+('; '.join(x['pair'] for x in cases) or 'No supported tested point')+' | '+('; '.join(f"{x['achieved_bytes_s_median']/GIB:.3f}" for x in cases) or 'UNAVAILABLE')+' |')
P={x['pair']:x for x in S['interference']}
def loss(p):return f"{100*P[p]['loss']['mean']:.2f}% mean, {100*P[p]['loss']['min']:.2f}–{100*P[p]['loss']['max']:.2f}% observed range" if p in P else 'UNAVAILABLE'
L+=['','Unstable pairs excluded from supported budgets: '+('; '.join(x['pair']+' (baseline CV '+str(round(x['baseline_CV_percent'],2))+'%, loaded '+str(round(x['loaded_CV_percent'],2))+'%)' for x in E.get('unstable_pairs_excluded_from_supported_budgets',[])) or 'none')+'. Two additional unchanged-binary repetitions investigate the initial noisy 500MiB/s small-dispatch pair; see raw/followup-v6-revision.json and raw/anomaly-dispatch500-initial3.json.','','3. **Burst versus smooth.** Small-dispatch compute at the nominal 100 MiB/s smooth stream loses '+loss('dispatch-104857600')+'; equal-nominal-average 3,000 MiB bursts every 30 seconds lose '+loss('burst30s')+'. The paired mean p99 increases and achieved rates are in the interference table. The separate boundary-instrumented plot aligns actual burst start/end events with native measurement time, CPU and GPU power. Only about two measured burst events per minute occur; whole-minute p99 can miss rare burst stalls, so these runs do not establish a safe worst-tail guarantee.','','4. **Simultaneous consumption by both GPUs.** Grouped 64 MiB H2D and D2H total payload rates are '+rate('both-h2d')+' / '+rate('both-d2h')+'. For the same 64 MiB size, isolated H2D is '+rate('gpu0-h2d-pinned-67108864')+' / '+rate('gpu1-h2d-pinned-67108864')+'.']
if all(n in B for n in ['both-h2d','gpu0-h2d-pinned-67108864','gpu1-h2d-pinned-67108864']):
 summed=sum(B[n]['rates']['median'] for n in ['gpu0-h2d-pinned-67108864','gpu1-h2d-pinned-67108864']);L.append(f"Observed both-card H2D is {100*B['both-h2d']['rates']['median']/summed:.2f}% of the sum of isolated same-size medians. The concurrent aggregate is measured directly, not assumed from that sum; grouped copies have equal delivered counts by construction.")
L+=['','5. **P2P and host bridging.** Direct CUDA P2P is unsupported both ways. Explicit GPU0→pinned RAM→GPU1 serial 3 MiB bridge is '+rate('bridge-0-1-3145728-serial')+', with median-of-repetition p50/p99 '+latent('bridge-0-1-3145728-serial')+' / '+latent('bridge-0-1-3145728-serial','latency_p99_ms')+'. The 32 KiB activation round trip p50/p99 is '+latent('bridge-roundtrip-activation')+' / '+latent('bridge-roundtrip-activation','latency_p99_ms')+'. Each bridge object additionally updates an 8-byte source validation tag: this extra H2D transaction is included in timing but excluded from the native payload-leg byte counter. Round-trip delivered bytes count both directions; its four transfer legs are not a one-way application bandwidth.','','6. **Expert-sized storage evidence.** Both paths have private seeded 16 GiB corpora and their own regular-file write controls. The following table uses 3 MiB random reads with explicit guest O_DIRECT, with no inference about host caches/physical media. p99 is the median of the three repetition-specific fio p99 values, not a pooled p99.','','| Visible path | QD1 rate | QD1 p99 | QD8 rate | QD8 p99 |','|---|---|---|---|---|']
for path in ['virtiofs','ext4']:
 a=path+'-randread-3145728-direct1-qd1';b=path+'-randread-3145728-direct1-qd8';L.append(f'| {path} | {rate(a)} | {fio_tail(a)} | {rate(b)} | {fio_tail(b)} |')
L+=['','Readiness for an SSD-backed expert tier must be judged against the promotion budget, queue depth and expert miss burst size, rather than one aggregate peak. Guest direct descriptors are recorded in raw/guest-direct-evidence.jsonl. virtiofs and ext4/QEMU block results are visible path/cache measurements; no physical SSD identity or cold-host-cache guarantee is available. Limited fio writes have independent full 256 MiB CRC32C readback after the timed write/final fsync. Actual native fio worker CPU/RSS is supplemented separately from the Python safety wrapper.','','7. **Layer split versus remote experts.** Without P2P, frequent per-layer remote work pays the staged transfer/launch/synchronization cost above. Inclusive residency promotions can be infrequent and avoid clean-eviction D2H; the immutable-store diagnostic validates completion before slot publication and skips already-ready IDs. The hardware data do not choose a Qwen runtime: actual expert routing, CPU fallback, MTP acceptance, output summation and useful token latency require same-token model A/B. That Strata experiment is queued separately and cannot be attributed to this surrogate campaign.','','8. **Retest after changing attachment or going bare metal.** Repeat inventory and loaded PCIe lane width/P2P first; use the same seeded corpus size and buffered/guest-direct read matrix on the new path. Repeat real file→RAM→GPU pipelines and the paired compute/transfer points near the observed interference knee. Where exposed, add host SSD identity, health and physical counters/cache state; do not assume all rates improve.','','9. **Next measurement.** A frozen same-token IQ3_S experiment comparing layer split and original/optimized helper, with identical initial expert capacities, equal warmup and suffix lookup disabled, plus routing/CPU-fallback/PCIe counters, most directly reduces the runtime uncertainty. For a predictive residency design, follow it with a held-out routing/miss trace replay under the measured achieved transfer budgets and paired token latency; no predictor was trained here.','','## Scoped before/after optimization observations','','| Reversible comparison | Median rate change | Interpretation |','|---|---:|---|']
for a,b,description in [('gpu0-h2d-pageable-3145728','gpu0-h2d-pinned-3145728','pageable → reusable pinned, same 3 MiB'),('bridge-0-1-67108864-serial','bridge-0-1-bulk-double','explicit bridge one → two buffers, same 64 MiB'),('ext4-pipeline-gpu0-b1','ext4-pipeline-gpu0-b3','real ext4 pipeline one → three buffers, same 3 MiB'),('virtiofs-pipeline-gpu0-b1','virtiofs-pipeline-gpu0-b3','real virtiofs pipeline one → three buffers, same 3 MiB'),('immutable-store-pack','immutable-store-inclusive','same synthetic delta stream: segments staging → prepared contiguous backing')]:
 L.append(f'| {description} | {change(a,b)} | Same-case mechanism comparison; distinct path/software cohort retained. |')
L+=['','Controller ranked/cooperative/quota rates, core-seconds and rolling-monitor interference are in summary.json. A 25% CPUQuota transient scope means one-quarter of one core; it neither caps memory bandwidth nor promises suppression of instantaneous bursts. Pipeline stage sums overlap and must not be added to reconstruct elapsed wall time. Reservoir store iteration latencies include no-transfer already-resident delta hits; payload bandwidth counts only promoted bytes.']
# Keep concurrent CPU work separate from the GPU useful-work metric.
combined=P.get('combined')
if combined:
 byraw={x.get('raw_stdout'):x for x in rows};cpu_losses=[]
 for o in combined['observations']:
  a=byraw.get(o['raw_A'],{});b=byraw.get(o['raw_B'],{})
  av=a.get('combined_cpu_useful_bytes',0)/a.get('actual_measured_seconds',1);bv=b.get('combined_cpu_useful_bytes',0)/b.get('actual_measured_seconds',1)
  if av:cpu_losses.append(1-bv/av)
 L+=['','## Combined useful work','','GPU useful-work loss for the paired combined CPU/GPU case: '+loss('combined')+'.']
 if cpu_losses:L.append(f'Concurrent CPU useful-byte-rate loss: {100*statistics.mean(cpu_losses):.2f}% mean, {100*min(cpu_losses):.2f}–{100*max(cpu_losses):.2f}% observed range over {len(cpu_losses)} paired repetitions. This is distinct from GPU FLOP/s; original byte counts and measured durations are retained.')
p=R/'report.md';text=p.read_text();a=text.index('## Direct answers');b=text.index('## Exclusions, failures',a);text=text[:a]+'\n'.join(L)+'\n\n'+text[b:];p.write_text(text)
print('Numerical hardware interpretation updated:',p)
